/**
 * A simple JDBC-based implementation of the {@link OwnerRepository} interface.
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Rob Harrop
 * @author Sam Brannen
 * @author Thomas Risberg
 * @author Mark Fisher
 * @author Antoine Rey
 * @author Vitaliy Fedoriv
 */
@DependsOnDatabaseInitialization
@Repository
@Profile("jdbc")
public class JdbcOwnerRepositoryImpl implements OwnerRepository {

    private NamedParameterJdbcTemplate namedParameterJdbcTemplate;

    private SimpleJdbcInsert insertOwner;

    public JdbcOwnerRepositoryImpl(DataSource dataSource) {

        this.insertOwner = new SimpleJdbcInsert(dataSource)
            .withTableName("owners")
            .usingGeneratedKeyColumns("id");

        this.namedParameterJdbcTemplate = new NamedParameterJdbcTemplate(dataSource);

    }


    /**
     * Loads {@link Owner Owners} from the data store by last name, returning all owners whose last name <i>starts</i> with
     * the given name; also loads the {@link Pet Pets} and {@link Visit Visits} for the corresponding owners, if not
     * already loaded.
     */
    @Override
    public Collection<Owner> findByLastName(String lastName) throws DataAccessException {
        Map<String, Object> params = new HashMap<>();
        params.put("lastName", lastName + "%");
        List<Owner> owners = this.namedParameterJdbcTemplate.query(
            "SELECT id, first_name, last_name, address, city, telephone, email, registration_date, customer_code, household_id, namesake_count FROM owners WHERE last_name like :lastName",
            params,
            BeanPropertyRowMapper.newInstance(Owner.class)
        );
        loadOwnersPetsAndVisits(owners);
        return owners;
    }

    @Override
    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
        Map<String, Object> params = new HashMap<>();
        params.put("lastName", lastName + "%");
        params.put("size", pageable.getPageSize());
        params.put("offset", pageable.getOffset());
        List<Owner> owners = this.namedParameterJdbcTemplate.query(
            "SELECT id, first_name, last_name, address, city, telephone, email, registration_date, customer_code, household_id, namesake_count FROM owners WHERE last_name like :lastName ORDER BY id LIMIT :size OFFSET :offset",
            params,
            BeanPropertyRowMapper.newInstance(Owner.class)
        );
        loadOwnersPetsAndVisits(owners);
        Long total = this.namedParameterJdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM owners WHERE last_name like :lastName",
            params,
            Long.class
        );
        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
    }

    /**
     * Loads the {@link Owner} with the supplied <code>id</code>; also loads the {@link Pet Pets} and {@link Visit Visits}
     * for the corresponding owner, if not already loaded.
     */
    @Override
    public Owner findById(int id) throws DataAccessException {
        Owner owner;
        try {
            Map<String, Object> params = new HashMap<>();
            params.put("id", id);
            owner = this.namedParameterJdbcTemplate.queryForObject(
                "SELECT id, first_name, last_name, address, city, telephone, email, registration_date, customer_code, household_id, namesake_count FROM owners WHERE id= :id",
                params,
                BeanPropertyRowMapper.newInstance(Owner.class)
            );
        } catch (EmptyResultDataAccessException ex) {
            throw new ObjectRetrievalFailureException(Owner.class, id);
        }
        loadPetsAndVisits(owner);
        return owner;
    }

    @Override
    public boolean existsByTelephone(String telephone) throws DataAccessException {
        Map<String, Object> params = new HashMap<>();
        params.put("telephone", telephone);
        Long count = this.namedParameterJdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM owners WHERE telephone = :telephone", params, Long.class);
        return count != null && count > 0;
    }

    @Override
    public List<Owner> findByLastNameIgnoringCase(String lastName) throws DataAccessException {
        Map<String, Object> params = new HashMap<>();
        params.put("lastName", lastName);
        return this.namedParameterJdbcTemplate.query(
            "SELECT id, first_name, last_name, address, city, telephone, email, registration_date, customer_code, household_id, namesake_count FROM owners WHERE LOWER(last_name) = :lastName",
            params,
            BeanPropertyRowMapper.newInstance(Owner.class));
    }

    @Override
    public long countByFirstNameAndLastNameIgnoringCase(String firstName, String lastName) throws DataAccessException {
        Map<String, Object> params = new HashMap<>();
        params.put("firstName", firstName);
        params.put("lastName", lastName);
        Long count = this.namedParameterJdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM owners WHERE LOWER(first_name) = :firstName AND LOWER(last_name) = :lastName",
            params, Long.class);
        return count == null ? 0 : count;
    }

    @Override
    public long countByCityIgnoringCase(String city) throws DataAccessException {
        Map<String, Object> params = new HashMap<>();
        params.put("city", city);
        Long count = this.namedParameterJdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM owners WHERE LOWER(city) = :city", params, Long.class);
        return count == null ? 0 : count;
    }

    @Override
    public long count() throws DataAccessException {
        Long count = this.namedParameterJdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM owners", new HashMap<String, Object>(), Long.class);
        return count == null ? 0 : count;
    }

    public void loadPetsAndVisits(final Owner owner) {
        Map<String, Object> params = new HashMap<>();
        params.put("id", owner.getId());
        final List<JdbcPet> pets = this.namedParameterJdbcTemplate.query(
            "SELECT pets.id as pets_id, name, birth_date, type_id, owner_id, visits.id as visit_id, visit_date, description, visits.pet_id as visits_pet_id FROM pets LEFT OUTER JOIN visits ON pets.id = visits.pet_id WHERE owner_id=:id ORDER BY pets.id",
            params,
            new JdbcPetVisitExtractor()
        );
        Collection<PetType> petTypes = getPetTypes();
        for (JdbcPet pet : pets) {
            pet.setType(EntityUtils.getById(petTypes, PetType.class, pet.getTypeId()));
            owner.addPet(pet);
        }
    }

    @Override
    public void save(Owner owner) throws DataAccessException {
        BeanPropertySqlParameterSource parameterSource = new BeanPropertySqlParameterSource(owner);
        if (owner.isNew()) {
            Number newKey = this.insertOwner.executeAndReturnKey(parameterSource);
            owner.setId(newKey.intValue());
        } else {
            this.namedParameterJdbcTemplate.update(
                "UPDATE owners SET first_name=:firstName, last_name=:lastName, address=:address, " +
                    "city=:city, telephone=:telephone, email=:email, registration_date=:registrationDate, customer_code=:customerCode, household_id=:householdId, namesake_count=:namesakeCount WHERE id=:id",
                parameterSource);
        }
    }

    public Collection<PetType> getPetTypes() throws DataAccessException {
        return this.namedParameterJdbcTemplate.query(
            "SELECT id, name FROM types ORDER BY name", new HashMap<String, Object>(),
            BeanPropertyRowMapper.newInstance(PetType.class));
    }

    /**
     * Loads the {@link Pet} and {@link Visit} data for the supplied {@link List} of {@link Owner Owners}.
     *
     * @param owners the list of owners for whom the pet and visit data should be loaded
     * @see #loadPetsAndVisits(Owner)
     */
    private void loadOwnersPetsAndVisits(List<Owner> owners) {
        for (Owner owner : owners) {
            loadPetsAndVisits(owner);
        }
    }

	@Override
	public Collection<Owner> findAll() throws DataAccessException {
		List<Owner> owners = this.namedParameterJdbcTemplate.query(
	            "SELECT id, first_name, last_name, address, city, telephone, email, registration_date, customer_code, household_id, namesake_count FROM owners",
	            new HashMap<String, Object>(),
	            BeanPropertyRowMapper.newInstance(Owner.class));
		for (Owner owner : owners) {
            loadPetsAndVisits(owner);
        }
	    return owners;
	}

    @Override
    public Page<Owner> findAll(Pageable pageable) throws DataAccessException {
        Map<String, Object> params = new HashMap<>();
        params.put("size", pageable.getPageSize());
        params.put("offset", pageable.getOffset());
        List<Owner> owners = this.namedParameterJdbcTemplate.query(
            "SELECT id, first_name, last_name, address, city, telephone, email, registration_date, customer_code, household_id, namesake_count FROM owners ORDER BY id LIMIT :size OFFSET :offset",
            params,
            BeanPropertyRowMapper.newInstance(Owner.class));
        loadOwnersPetsAndVisits(owners);
        Long total = this.namedParameterJdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM owners",
            params,
            Long.class
        );
        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
    }

	@Override
	@Transactional
	public void delete(Owner owner) throws DataAccessException {
		Map<String, Object> ownerParams = new HashMap<>();
		ownerParams.put("id", owner.getId());
        List<Pet> pets = owner.getPets();
        // cascade delete pets
        for (Pet pet : pets){
        	Map<String, Object> petParams = new HashMap<>();
        	petParams.put("id", pet.getId());
        	// cascade delete visits
        	List<Visit> visits = pet.getVisits();
            for (Visit visit : visits){
            	Map<String, Object> visitParams = new HashMap<>();
            	visitParams.put("id", visit.getId());
            	this.namedParameterJdbcTemplate.update("DELETE FROM visits WHERE id=:id", visitParams);
            }
            this.namedParameterJdbcTemplate.update("DELETE FROM pets WHERE id=:id", petParams);
        }
        this.namedParameterJdbcTemplate.update("DELETE FROM owners WHERE id=:id", ownerParams);
	}


}

